--- a/pipeline/pairs.py
+++ b/pipeline/pairs.py
@@ -24,5 +24,18 @@

 def pair_stats(pairs):
     if not pairs:
-        return {"n": 0, "mean_margin": 0.0}
-    return {"n": len(pairs), "mean_margin": sum(p["margin"] for p in pairs) / len(pairs)}
+        return {"n": 0, "mean_margin": 0.0, "median_margin": 0.0, "by_source": {}}
+    n = len(pairs)
+    margins = sorted(p["margin"] for p in pairs)
+    mean_margin = sum(margins) / n
+    # compute median
+    if n % 2 == 1:
+        median_margin = margins[n // 2]
+    else:
+        median_margin = 0.5 * (margins[n // 2 - 1] + margins[n // 2])
+    # counts per source
+    by_source = {}
+    for p in pairs:
+        src = p.get("source")
+        by_source[src] = by_source.get(src, 0) + 1
+    return {"n": n, "mean_margin": mean_margin, "median_margin": median_margin, "by_source": by_source}
